{
  "format": 1,
  "id": "analog-clock",
  "name": "アナログ時計",
  "type": "script",
  "description": "端末の時刻で動くアナログ時計(スクリプト型のサンプル)",
  "icon": "clock",
  "category": "time",
  "keywords": [
    "とけい",
    "時計",
    "clock"
  ],
  "fps": 15,
  "aspect": 1,
  "script": "// アナログ時計: 変形(translate・rotate)と文字の例。1秒に15コマで十分なので、fps は15にしている。
function hand(angle, length, width, color) {
  ctx.save();
  ctx.rotate(angle);
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(0, length * 0.15);
  ctx.lineTo(0, -length);
  ctx.stroke();
  ctx.restore();
}

function frame(t, dt) {
  var w = screen.width, h = screen.height, r = Math.min(w, h) * 0.42;
  var ink = screen.dark ? '#dddddd' : '#222222';
  ctx.fillStyle = screen.dark ? '#000000' : '#ffffff';
  ctx.fillRect(0, 0, w, h);
  ctx.save();
  ctx.translate(w / 2, h / 2);
  ctx.strokeStyle = ink;
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, Math.PI * 2);
  ctx.stroke();
  ctx.lineCap = 'round';
  for (var i = 0; i < 60; i++) {
    var a = i * Math.PI / 30;
    var major = i % 5 === 0;
    var inner = major ? 0.85 : 0.92;
    ctx.lineWidth = major ? 4 : 1.5;
    ctx.beginPath();
    ctx.moveTo(Math.sin(a) * r * inner, -Math.cos(a) * r * inner);
    ctx.lineTo(Math.sin(a) * r * 0.97, -Math.cos(a) * r * 0.97);
    ctx.stroke();
  }
  ctx.fillStyle = ink;
  ctx.font = 'bold ' + Math.round(r * 0.16) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (var n = 1; n <= 12; n++) {
    var b = n * Math.PI / 6;
    ctx.fillText(String(n), Math.sin(b) * r * 0.7, -Math.cos(b) * r * 0.7);
  }
  var now = new Date();
  var s = now.getSeconds() + now.getMilliseconds() / 1000;
  var m = now.getMinutes() + s / 60;
  var hr = (now.getHours() % 12) + m / 60;
  hand(hr * Math.PI / 6, r * 0.5, 8, ink);
  hand(m * Math.PI / 30, r * 0.75, 5, ink);
  hand(s * Math.PI / 30, r * 0.85, 2, 'crimson');
  ctx.fillStyle = 'crimson';
  ctx.beginPath();
  ctx.arc(0, 0, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}
"
}

{
  "format": 1,
  "id": "bouncing-ball",
  "name": "跳ねるボール",
  "type": "script",
  "description": "壁で跳ね返るボール。タップで足せます(スクリプト型のサンプル)",
  "icon": "circle.circle",
  "category": "play",
  "keywords": [
    "ぼーる",
    "アニメーション"
  ],
  "controls": [
    {
      "id": "speed",
      "type": "slider",
      "label": "速さ",
      "min": 50,
      "max": 400,
      "step": 10,
      "value": 200
    },
    {
      "id": "clear",
      "type": "button",
      "label": "すべて消す"
    }
  ],
  "script": "// 跳ねるボール: スライダー(速さ)、ボタン(消す)、タップで足す。グラデーションの例。
var balls = [];
var speed = 200;

function add(x, y) {
  if (balls.length >= 30) balls.shift();
  var a = random.range(0, Math.PI * 2);
  balls.push({ x: x, y: y, vx: Math.cos(a), vy: Math.sin(a), r: random.range(12, 26), hue: random.int(0, 359) });
}

function setup() {
  for (var i = 0; i < 3; i++) add(random.range(40, screen.width - 40), random.range(40, screen.height - 40));
}

function onInput(name, value) {
  if (name === 'speed') speed = value;
  if (name === 'clear') balls = [];
}

function onTouch(e) {
  if (e.type === 'down') {
    add(e.x, e.y);
    sound.play('pop');
  }
}

function frame(t, dt) {
  var w = screen.width, h = screen.height;
  ctx.fillStyle = screen.dark ? '#111111' : '#f4f4f4';
  ctx.fillRect(0, 0, w, h);
  for (var i = 0; i < balls.length; i++) {
    var b = balls[i];
    b.x += b.vx * speed * dt;
    b.y += b.vy * speed * dt;
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > w - b.r) { b.x = w - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy); }
    if (b.y > h - b.r) { b.y = h - b.r; b.vy = -Math.abs(b.vy); }
    var g = ctx.createRadialGradient(b.x - b.r * 0.3, b.y - b.r * 0.3, 2, b.x, b.y, b.r);
    g.addColorStop(0, 'hsl(' + b.hue + ', 90%, 75%)');
    g.addColorStop(1, 'hsl(' + b.hue + ', 80%, 45%)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = screen.dark ? '#aaaaaa' : '#555555';
  ctx.font = '13px sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('タップでボールを足す(' + balls.length + '個)', 10, 10);
}
"
}

