  ctx.fillRect(0, 0, w, groundY);
  ctx.fillStyle = '#5a9e3c';
  ctx.fillRect(0, groundY, w, h - groundY);
  x += 10 * scale * dt;
  if (x > w + size) x = -size;
  var f = Math.floor(t * 6) % 2;
  var bob = f === 0 ? 0 : -scale;
  ctx.imageSmoothingEnabled = false;
