{
  "format": 1,
  "id": "place-compass",
  "name": "地点を指すコンパス",
  "type": "script",
  "description": "登録した地点の方向を、端末の方位に合わせて矢印で指します(アプリのデータとセンサーを使うサンプル)",
  "icon": "location.north.circle",
