{
  "format": 1,
  "id": "pressure-graph",
  "name": "気圧の小さなグラフ",
  "type": "script",
  "description": "記録した気圧と予報を、前後24時間の小さなグラフにします(アプリのデータを読むサンプル)",
  "icon": "barometer",
  "category": "measure",
  "keywords": [
    "きあつ",
    "気圧",
    "グラフ",
    "頭痛"
  ],
  "permissions": [
    "pressure"
  ],
  "fps": 15,
  "aspect": 1.6,
  "script": "// 気圧の小さなグラフ: 端末で記録した気圧(実線)と予報(点線)を、前後24時間で描く(app.pressure)。データが変わったときだけ描き直す。
var pressure = null, dirty = true, lastKey = '', lastMinute = -1;

function setup() { pressure = app.pressure; }

function onData(kind) {
  if (kind === 'pressure') { pressure = app.pressure; dirty = true; }
}

function frame() {
  var key = screen.width + 'x' + screen.height + (screen.dark ? 'd' : 'l');
  var minute = Math.floor(Date.now() / 60000);
  if (key !== lastKey || minute !== lastMinute) { lastKey = key; lastMinute = minute; dirty = true; }
  if (!dirty) return;
  dirty = false;
  draw();
}

function draw() {
  var dark = screen.dark, W = screen.width, H = screen.height;
  var fg = dark ? '#f2f2f7' : '#1c1c1e', sub = dark ? '#98989f' : '#6c6c70', grid = dark ? '#2c2c2e' : '#e5e5ea';
  var blue = dark ? '#0a84ff' : '#007aff';
  ctx.fillStyle = dark ? '#000000' : '#ffffff';
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  if (!pressure) {
    ctx.fillStyle = sub;
    ctx.font = '15px sans-serif';
    ctx.fillText(app.permissions && app.permissions.pressure ? '気圧のデータがまだありません' : '「気圧」のデータを許可していません', 16, 24);
    return;
  }
  ctx.fillStyle = fg;
  ctx.font = 'bold 40px sans-serif';
  ctx.fillText(pressure.latest === null ? '--' : pressure.latest.toFixed(1), 16, 12);
  var w = ctx.measureText(pressure.latest === null ? '--' : pressure.latest.toFixed(1)).width;
  ctx.font = '16px sans-serif';
  ctx.fillText('hPa', 22 + w, 32);
  var change = pressure.change3h;
  if (change) {
    ctx.fillStyle = change.delta <= -3 ? '#ff9500' : sub;
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(change.text, 16, 62);
  }

  var now = Date.now(), from = now - 24 * 3600000, to = now + 24 * 3600000;
  var measured = pressure.measured.filter(function (p) { return p.time >= from && p.hPa !== null; });
  var forecast = pressure.forecast.filter(function (p) { return p.time >= from && p.time <= to && p.hPa !== null; });
  var values = measured.concat(forecast).map(function (p) { return p.hPa; });
  if (!values.length) return;
  var lo = Math.min.apply(null, values), hi = Math.max.apply(null, values);
  var mid = (lo + hi) / 2, span = Math.max(hi - lo + 2, 6);
  lo = Math.floor(mid - span / 2); hi = Math.ceil(mid + span / 2);
  var left = 44, right = W - 12, top = 92, bottom = H - 26;
  if (bottom - top < 60) return;
  function px(t) { return left + (t - from) / (to - from) * (right - left); }
  function py(v) { return bottom - (v - lo) / (hi - lo) * (bottom - top); }

  ctx.font = '11px sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  var stepHPa = hi - lo > 12 ? 4 : 2;
  for (var v = Math.ceil(lo / stepHPa) * stepHPa; v <= hi; v += stepHPa) {
    ctx.strokeStyle = grid;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(left, py(v)); ctx.lineTo(right, py(v)); ctx.stroke();
    ctx.fillStyle = sub;
    ctx.fillText(String(v), left - 6, py(v));
  }
  ctx.strokeStyle = sub;
  ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(px(now), top); ctx.lineTo(px(now), bottom); ctx.stroke();
  ctx.setLineDash([]);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = sub;
  ctx.fillText('24時間前', left + 24, bottom + 6);
  ctx.fillText('今', px(now), bottom + 6);
  ctx.fillText('24時間後', right - 24, bottom + 6);

  function line(points, color, width, dash) {
    if (points.length < 2) return;
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.setLineDash(dash);
    ctx.beginPath();
    ctx.moveTo(px(points[0].time), py(points[0].hPa));
    for (var i = 1; i < points.length; i++) ctx.lineTo(px(points[i].time), py(points[i].hPa));
    ctx.stroke();
    ctx.setLineDash([]);
  }
  line(forecast.filter(function (p) { return p.time >= now - 3600000; }), sub, 2, [5, 4]);
  line(measured, blue, 2.5, []);
}
"
}

{
  "format": 1,
  "id": "tap-target",
  "name": "的あてゲーム",
  "type": "script",
  "description": "30秒で、出てくる的をタップします。最高点を保存します(スクリプト型のサンプル)",
  "icon": "target",
  "category": "play",
  "keywords": [
    "まと",
    "ゲーム",
    "タップ"
  ],
  "controls": [
    {
      "id": "start",
      "type": "button",
      "label": "はじめから"
    }
  ],
  "script": "// 的あてゲーム: 30秒で、出てくる的をタップする。最高点は保存領域(storage)に残す。効果音と振動。
var ROUND = 30;
var targets = [];
var effects = [];
var score = 0;
var best = 0;
var timeLeft = 0;
var playing = false;
var spawn = 0;

function setup() {
  best = storage.get('best') || 0;
}

function start() {
  targets = [];
  effects = [];
  score = 0;
  timeLeft = ROUND;
  playing = true;
  spawn = 0;
  sound.play('beep');
}

function onInput(name) {
  if (name === 'start') start();
}

function onTouch(e) {
  if (e.type !== 'down') return;
  if (!playing) { start(); return; }
  for (var i = targets.length - 1; i >= 0; i--) {
    var tg = targets[i], dx = e.x - tg.x, dy = e.y - tg.y;
    if (dx * dx + dy * dy <= tg.r * tg.r) {
      var points = tg.r < 24 ? 3 : 1;
      score += points;
      effects.push({ x: tg.x, y: tg.y, age: 0, text: '+' + points });
      targets.splice(i, 1);
      sound.play('coin');
      haptic('light');
      return;
    }
  }
  sound.play('click');
}

function update(dt, w, h) {
  timeLeft -= dt;
  spawn -= dt;
  if (spawn <= 0 && targets.length < 6) {
    spawn = random.range(0.35, 0.8);
    var r = random.range(18, 40);
    targets.push({ x: random.range(r, w - r), y: random.range(60 + r, h - r), r: r, life: random.range(1.2, 2.2), age: 0 });
  }
  for (var i = targets.length - 1; i >= 0; i--) {
    targets[i].age += dt;
    if (targets[i].age >= targets[i].life) targets.splice(i, 1);
  }
  if (timeLeft <= 0) {
    playing = false;
    targets = [];
    if (score > best) {
      best = score;
      storage.set('best', best);
      sound.play('success');
      haptic('success');
    } else {
      sound.play('failure');
    }
  }
}

function frame(t, dt) {
  var w = screen.width, h = screen.height;
  if (playing) update(dt, w, h);
  ctx.fillStyle = screen.dark ? '#101820' : '#eef4f8';
  ctx.fillRect(0, 0, w, h);
  for (var j = 0; j < targets.length; j++) {
    var g = targets[j];
    ctx.globalAlpha = Math.min(1, (1 - g.age / g.life) * 3);
    ctx.fillStyle = '#e63946';
    ctx.beginPath(); ctx.arc(g.x, g.y, g.r, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(g.x, g.y, g.r * 0.62, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#e63946';
    ctx.beginPath(); ctx.arc(g.x, g.y, g.r * 0.28, 0, Math.PI * 2); ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.font = 'bold 20px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (var m = effects.length - 1; m >= 0; m--) {
    var fx = effects[m];
    fx.age += dt;
    if (fx.age > 0.6) { effects.splice(m, 1); continue; }
    ctx.globalAlpha = 1 - fx.age / 0.6;
    ctx.fillStyle = '#2a9d8f';
    ctx.fillText(fx.text, fx.x, fx.y - fx.age * 40);
  }
  ctx.globalAlpha = 1;
  ctx.fillStyle = screen.dark ? '#eeeeee' : '#222222';
  ctx.font = 'bold 18px sans-serif';
  ctx.textBaseline = 'top';
  ctx.textAlign = 'left';
  ctx.fillText('点 ' + score, 12, 12);
  ctx.textAlign = 'right';
  ctx.fillText(playing ? '残り ' + Math.ceil(timeLeft) + '秒' : '最高 ' + best, w - 12, 12);
  if (!playing) {
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = 'bold 22px sans-serif';
    ctx.fillText('タップで始める(' + ROUND + '秒)', w / 2, h / 2);
    ctx.font = '14px sans-serif';
    ctx.fillText('小さい的は3点', w / 2, h / 2 + 30);
  }
}
"
}

{
  "format": 1,
  "id": "weather-board",
  "name": "自分好みの天気",
  "type": "script",
  "description": "アプリが取得した天気と警報を、自分好みの形で表示します(アプリのデータを読むサンプル)",
  "icon": "cloud.sun",
